// Security → Activity tab (audit feed), AS GRAPH SOURCE (#3646, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the security lib surface via the security graph-platform,
// and the sibling tab bodies as graph records addressed by specifier). Behaviour runs here, so there is
// no forked render path. (The prose deliberately does not spell a bare component-store path: `bsc ui set`
// scans srcText for import specifiers and read this sentence as an unresolvable import, warning on every
// write. A record IS the screen, and its comments are scanned like code.)
// Logs — Activity tab (#1643, split from what was then SecurityWorkspace; the Security workspace
// dissolved into Logs in the-logs-workspace-scaffold-and-activity).
//
// The per-pane tool-attempt feed (#257): summary cards, decision + console filters,
// and the table of allow/ask/block rows. Row derivation + filtering + counts are pure
// (./lib/auditRows); this is render + light filter view state.
// Preview note: `auditRows` (filter/decision-count helpers) and the `AgentProfile`/`ConsoleSession`
// types are app-internal (unresolvable in this sandbox) — inlined locally below with sample defaults
// so this tab previews standalone; every prop still overrides the sample when composed by SecurityWorkspace.

import { StatTile } from "@/shared/ui/data/StatTile";
import { SelectField } from "@/shared/ui/controls/Field";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

interface AgentProfile { id: string; name: string; color: string }
interface ConsoleSession { id: string; name: string }
type DecFilter = "all" | "allow" | "ask" | "block";
interface AuditDisplayRow { ts: number; console: string; pane: string; profileId: string; decision: "allow" | "ask" | "block"; kind: "cmd" | "net" | "tool"; target: string }

function filterAuditRows(rows: AuditDisplayRow[], decision: DecFilter, console: string): AuditDisplayRow[] {
  return rows.filter((r) => (decision === "all" || r.decision === decision) && (console === "all" || r.console === console));
}
function fmtAuditTime(ts: number): string {
  return new Date(ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

const NOW = 1700000000000;
const SAMPLE_CONSOLES: ConsoleSession[] = [{ id: "c1", name: "design-studio" }, { id: "c2", name: "infra" }];
const SAMPLE_PROFILES: Record<string, AgentProfile> = {
  pf_sandbox: { id: "pf_sandbox", name: "Sandbox", color: "oklch(0.78 0.14 70)" },
  pf_reviewer: { id: "pf_reviewer", name: "Reviewer", color: "oklch(0.68 0.18 25)" },
};
const SAMPLE_ROWS: AuditDisplayRow[] = [
  { ts: NOW, console: "design-studio", pane: "worker-1", profileId: "pf_sandbox", decision: "allow", kind: "cmd", target: "cargo build" },
  { ts: NOW - 40000, console: "design-studio", pane: "worker-2", profileId: "pf_reviewer", decision: "ask", kind: "tool", target: "edit src/App.tsx" },
  { ts: NOW - 90000, console: "infra", pane: "worker-3", profileId: "pf_sandbox", decision: "block", kind: "net", target: "fetch internal-api.example.com" },
  { ts: NOW - 150000, console: "design-studio", pane: "worker-1", profileId: "pf_sandbox", decision: "allow", kind: "cmd", target: "npm test" },
];

export interface ActivityTabProps {
  rows?: AuditDisplayRow[];
  consoles?: ConsoleSession[];
  actDecision?: DecFilter; setActDecision?: (d: DecFilter) => void;
  actConsole?: string; setActConsole?: (c: string) => void;
  allow?: number; ask?: number; block?: number;
  find?: (id: string) => AgentProfile | undefined;
}

export function ActivityTab({
  rows = SAMPLE_ROWS, consoles = SAMPLE_CONSOLES,
  actDecision = "all", setActDecision = () => {}, actConsole = "all", setActConsole = () => {},
  allow = SAMPLE_ROWS.filter((r) => r.decision === "allow").length,
  ask = SAMPLE_ROWS.filter((r) => r.decision === "ask").length,
  block = SAMPLE_ROWS.filter((r) => r.decision === "block").length,
  find = (id: string) => SAMPLE_PROFILES[id],
}: ActivityTabProps) {
  const shown = filterAuditRows(rows, actDecision, actConsole);
  const decColor = (d: DecFilter) => (d === "allow" ? "var(--success)" : d === "ask" ? "var(--accent)" : d === "block" ? "var(--danger)" : "var(--fg-dim)");
  const decChip = (d: DecFilter, label: string, n?: number) => {
    const on = actDecision === d;
    return (
      <Box as="span" key={d} onClick={() => setActDecision(d)} style={{
        display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px", borderRadius: 999, cursor: "pointer", fontSize: 11,
        border: on ? "1px solid var(--accent)" : "1px solid var(--border-soft)", background: on ? "var(--bg-elev2)" : "transparent", color: on ? "var(--fg)" : "var(--fg-muted)",
      }}>
        <Box as="span" bg={decColor(d)} radius={99} style={{ width: 6, height: 6 }} />{label}{n !== undefined && <Text as="span" tone="dim" style={{ marginLeft: 2 }}>{n}</Text>}
      </Box>
    );
  };
  const COLS = "64px 1fr 100px 1fr 80px";
  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10, marginBottom: 14 }}>
        <StatTile k="decisions" v={rows.length} sub={<>across {consoles.length} consoles</>} />
        <StatTile k="auto-allowed" v={allow} tone="success" sub="ran without a prompt" />
        <StatTile k="prompted" v={ask} tone="accent" sub="you confirmed" />
        <StatTile k="blocked" v={block} tone="danger" sub="policy denied" />
      </Box>

      <Row align="center" gap={10} wrap style={{ marginBottom: 12 }}>
        <Text as="span" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em" }}>decision</Text>
        <Row gap={6} align="stretch">
          {decChip("all", "all")}
          {decChip("allow", "allowed", allow)}
          {decChip("ask", "asked", ask)}
          {decChip("block", "blocked", block)}
        </Row>
        <Text as="span" mono size={10} tone="dim" style={{ marginLeft: 14, textTransform: "uppercase", letterSpacing: ".05em" }}>console</Text>
        <SelectField style={{ width: 150 }} value={actConsole} onChange={setActConsole}>
          <option value="all">all consoles</option>
          {consoles.map((c) => <option key={c.id} value={c.name}>{c.name}</option>)}
        </SelectField>
        <Box style={{ flex: 1 }} />
        <Text as="span" mono size={10} tone="dim">per the configured policy</Text>
      </Row>

      <Box border="soft" radius={7} style={{ overflow: "hidden" }}>
        <Box style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
          <Box as="span">time</Box><Box as="span">console › pane</Box><Box as="span">profile</Box><Box as="span">command / action</Box><Box as="span">decision</Box>
        </Box>
        {shown.length === 0 && (
          <Text as="div" mono tone="dim" size={11.5} style={{ padding: "18px 14px" }}>
            No activity yet. Tool attempts are logged once a pane has a profile or role assigned.
          </Text>
        )}
        {shown.map((r, i) => {
          const p = find(r.profileId);
          const sym = r.decision === "allow" ? "✓" : r.decision === "ask" ? "◑" : "✗";
          const decLabel = r.decision === "allow" ? "allowed" : r.decision === "ask" ? "asked" : "blocked";
          const kindGlyph = r.kind === "cmd" ? "$" : r.kind === "net" ? "⇡" : "⚒";
          return (
            <Box key={i} style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, alignItems: "center", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
              <Text as="span" mono size={10.5} tone="dim">{fmtAuditTime(r.ts)}</Text>
              <Text as="span" tone="muted" style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.console} <Text as="span" tone="dim">›</Text> {r.pane}</Text>
              <Box as="span" style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>{p && <Box as="span" bg={p.color} radius={99} style={{ width: 7, height: 7 }} />}{p?.name ?? r.profileId}</Box>
              <Box as="span" style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}><Text as="span" tone="dim">{kindGlyph}</Text> {r.target}</Box>
              <Text as="span" mono size={10.5} style={{ color: decColor(r.decision) }}>{sym} {decLabel}</Text>
            </Box>
          );
        })}
      </Box>
    </Box>
  );
}
